/*
 * RTE_Components.h - minimal stub for the raw-CMake (non-Keil-RTE) build.
 *
 * CMSIS-RTOS2 / RTX source variant pulls in "RTE_Components.h" unconditionally
 * from rtx_core_c.h and os_systick.c. In a Keil MDK + RTE workflow this file is
 * generated by the RTE manager; here we provide the single definition it is
 * consulted for: the CMSIS device header, so that
 *
 *     #include CMSIS_device_header
 *
 * resolves to "M55M1.h".
 *
 * SPDX-License-Identifier: Apache-2.0
 */
#ifndef RTE_COMPONENTS_H
#define RTE_COMPONENTS_H

#define CMSIS_device_header "M55M1.h"

#endif  /* RTE_COMPONENTS_H */
